		if kind == reflect.Int64 {
			switch value.Interface().(type) {
			case time.Duration:
				duration, err := time.ParseDuration(val)
				if err != nil {
					return err
				}
				value.Set(reflect.ValueOf(duration))
				return nil
			}
		}
		intBitSize := map[reflect.Kind]int{
			reflect.Int:   0,
			reflect.Int8:  8,
			reflect.Int16: 16,
			reflect.Int32: 32,
			reflect.Int64: 64,
		}
		intText := map[bool]string{true: "0", false: val}[val == ""]
		intVal, err := strconv.ParseInt(intText, 10, intBitSize[kind])
		if err == nil {
			value.SetInt(intVal)
		}
		return err
	case reflect.Uint, reflect.Uint8, reflect.Uint16, reflect.Uint32, reflect.Uint64:
		uintBitSize := map[reflect.Kind]int{
			reflect.Uint:   0,
			reflect.Uint8:  8,
			reflect.Uint16: 16,
			reflect.Uint32: 32,
			reflect.Uint64: 64,
		}
		uintText := map[bool]string{true: "0", false: val}[val == ""]
		uintVal, err := strconv.ParseUint(uintText, 10, uintBitSize[kind])
		if err == nil {
			value.SetUint(uintVal)
		}
		return err
	case reflect.Bool:
		return setBoolField(val, value)
	case reflect.Float32, reflect.Float64:
		floatBitSize := map[reflect.Kind]int{
			reflect.Float32: 32,
			reflect.Float64: 64,
		}
		floatText := map[bool]string{true: "0.0", false: val}[val == ""]
		floatVal, err := strconv.ParseFloat(floatText, floatBitSize[kind])
		if err == nil {
			value.SetFloat(floatVal)
		}
		return err
	case reflect.String:
		value.SetString(val)
	case reflect.Struct:
		switch value.Interface().(type) {
		case time.Time:
			return setTimeField(val, field, value)
		case multipart.FileHeader:
			raw := bytesconv.StringToBytes(val)
			dest := value.Addr().Interface()
			return json.Unmarshal(raw, dest)
		}
		raw := bytesconv.StringToBytes(val)
		dest := value.Addr().Interface()
		return json.Unmarshal(raw, dest)
	case reflect.Map:
		raw := bytesconv.StringToBytes(val)
		dest := value.Addr().Interface()
		return json.Unmarshal(raw, dest)
	case reflect.Ptr:
		if !value.Elem().IsValid() {
			value.Set(reflect.New(value.Type().Elem()))
		}
		return setWithProperType(val, value.Elem(), field)
	default:
		return errUnknownType
	}
	return nil
