package binding

import (
	"bytes"
	"mime/multipart"
	"net/http"
	"testing"
)

func TestTmpReproNonMandatoryFile(t *testing.T) {
	var body bytes.Buffer
	mw := multipart.NewWriter(&body)
	mw.WriteField("name", "name")
	mw.WriteField("email", "email")
	// file part with empty filename (browser sends this when no file selected)
	if _, err := mw.CreateFormFile("file", ""); err != nil {
		t.Fatal(err)
	}
	mw.Close()

	req, _ := http.NewRequest("POST", "/", &body)
	req.Header.Set("Content-Type", MIMEMultipartPOSTForm+"; boundary="+mw.Boundary())

	var s struct {
		Name  string                `form:"name" binding:"required"`
		Email string                `form:"email" binding:"required"`
		File  *multipart.FileHeader `form:"file"`
	}
	if err := FormMultipart.Bind(req, &s); err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if s.Name != "name" || s.Email != "email" {
		t.Fatalf("fields not bound: %v %v", s.Name, s.Email)
	}
}
